        yield 1
        await Promise.resolve()
        yield 2
        await Promise.resolve()
        yield 3
    }

    const start = mobx.flow(async function* () {
        let total = 0
        for await (const number of someNumbers()) {
            total += number
        }
        return total
    })

    const p = start()
    const res = await p
    expect(res).toBe(6)
})

test("flow support throwing async generators", async () => {
